class CFG:
    # -- data -----------------------------------------------------------------
    data_root, ann_mat, img_base, desc_paths = DATA_ROOT, ANN_MAT, IMG_BASE, DESC_PATHS
    work_dir, cache_dir, array_dir, runs_dir = WORK_DIR, CACHE_DIR, ARRAY_DIR, RUNS_DIR
