def mask_emotion_words(text: str) -> Tuple[str, int]:
    """Replace every lexicon word (whole word, any case) by [MASK]; returns (text, number replaced)."""
    out, n = _LEXICON_RE.subn(MASK_TOKEN, text)
    return out, int(n)


